// one case per variant (all of them), reading the variant's fields by name
function isPersonal(payer: Payer): Bool {
  match (payer) { CUSTOMER => true, COMPANY { billingEmail } => billingEmail == null }
}

M2.to:
// one case per variant (all of them), naming it by its tag and reading the variant's fields by name
function isPersonal(payer: Payer): Bool {
  match (payer) { when { kind: Payer.CUSTOMER }: true; when { kind: Payer.COMPANY, billingEmail }: billingEmail == null; }
}

