// one handler per variant (all of them), reading the variant's fields from its parameter
function isPersonal(payer: Payer): Bool {
  match(payer).with({ kind: Payer.CUSTOMER }, p => true).with({ kind: Payer.COMPANY }, p => p.billingEmail == null).exhaustive()
}
